#include "unity.h"
#include "header.h"
#include "helpers.h"

typedef struct {
    char *buffer;
    size_t buffer_size;
    int pipe_read_fd;
    int pipe_write_fd;
    int saved_stdout_fd;
} stdout_capture_t;

void setUp(void) { }
void tearDown(void) { }

void unit_test_printEPS_basic_eps_output(void) {
    // Setup: create a small set of observations and centroids
    // 2 clusters, 4 points, each cluster has 2 points
    observation pts[4];
    cluster cent[2];
    size_t len = 4;
    int k = 2;

    // Assign points to two clusters, spread out so min/max are not equal
    pts[0].x = 1.0; pts[0].y = 2.0; pts[0].group = 0;
    pts[1].x = 2.0; pts[1].y = 3.0; pts[1].group = 0;
    pts[2].x = 8.0; pts[2].y = 9.0; pts[2].group = 1;
    pts[3].x = 9.0; pts[3].y = 10.0; pts[3].group = 1;

    // Centroids for each cluster
    cent[0].x = 1.5; cent[0].y = 2.5; cent[0].count = 2;
    cent[1].x = 8.5; cent[1].y = 9.5; cent[1].count = 2;

    // Capture stdout
    stdout_capture_t *cap = capture_stdout_start();

    // Test: call function under test
    printEPS(pts, len, cent, k);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);

    // Assertions: output should contain EPS header and centroid marker
    TEST_ASSERT_NOT_NULL(output);
    assert_stdout_contains(cap, "%!PS-Adobe-3.0 EPSF-3.0");
    assert_stdout_contains(cap, "BoundingBox");
    assert_stdout_contains(cap, "setrgbcolor");
    assert_stdout_contains(cap, "c { .25 sub exch .25 sub exch .5 0 360 arc fill } def");
    assert_stdout_contains(cap, "s { moveto -2 0 m 2 2 l 2 -2 l -2 -2 l closepath");
    assert_stdout_contains(cap, "EOF");

    // Clean up
    if (output) free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_printEPS_basic_eps_output);
    return UNITY_END();
}


